    sl->ref_cache[0][scan8[13] + 1] =

    sl->ref_cache[1][scan8[5]  + 1] =

    sl->ref_cache[1][scan8[7]  + 1] =

    sl->ref_cache[1][scan8[13] + 1] = PART_NOT_AVAILABLE;



    if (sl != h->slice_ctx) {

