 int cb_shift = subfrm -> grid_index ;
 int cb_sign = subfrm -> pulse_sign ;
 int cb_pos = subfrm -> pulse_pos ;
 int offset , beta , lag ;
 for ( i = 0 ;
 i < 8 ;
 i += 2 ) {
 offset = ( ( cb_pos & 7 ) << 3 ) + cb_shift + i ;
 vector [ offset ] = ( cb_sign & 1 ) ? cb_gain : - cb_gain ;
 cb_pos >>= 3 ;
 cb_sign >>= 1 ;
