 lag = pitch_contrib [ subfrm -> ad_cb_gain << 1 ] + pitch_lag + subfrm -> ad_cb_lag - 1 ;
 beta = pitch_contrib [ ( subfrm -> ad_cb_gain << 1 ) + 1 ] ;
 if ( lag < SUBFRAME_LEN - 2 ) {
 for ( i = lag ;
 i < SUBFRAME_LEN ;
 i ++ ) vector [ i ] += beta * vector [ i - lag ] >> 15 ;
 }
 }
 }

