        switch(*ptype) {

        case 'F':

            /* file completion */

            completion_index = strlen(str);

            file_completion(str);

            break;

        case 'B':

            /* block device name completion */

            completion_index = strlen(str);

            bdrv_iterate(block_completion_it, (void *)str);

            break;

        default:

            break;

        }

    }

    for(i = 0; i < nb_args; i++)

        qemu_free(args[i]);

