            int pix_per_byte = context->is_mono ? 8 : 1;

            for (i = 0, j = 0; j < buf_size && i<avpkt->size; i++, j++) {

                dst[j] = buf[i];

                row_pix += pix_per_byte;

                if (row_pix >= avctx->width) {

                    i += stride - (i % stride) - 1;

                    j += 16 - (j % 16) - 1;

                    row_pix = 0;

                }

            }

        } else if (avctx->bits_per_coded_sample == 4) {

            for (i = 0, j = 0; 2 * j + 1 < buf_size && i<avpkt->size; i++, j++) {

                dst[2 * j + 0] = buf[i] >> 4;

                dst[2 * j + 1] = buf[i] & 15;

                row_pix += 2;

                if (row_pix >= avctx->width) {

