    s->coalesced_mmio = 0;

#endif



    s->broken_set_mem_region = 1;

#ifdef KVM_CAP_JOIN_MEMORY_REGIONS_WORKS

    ret = kvm_ioctl(s, KVM_CHECK_EXTENSION, KVM_CAP_JOIN_MEMORY_REGIONS_WORKS);

