    if (ret < 0)

        goto err;



    kvm_state = s;



    return 0;



err:

    if (s) {

        if (s->vmfd != -1)

            close(s->vmfd);

        if (s->fd != -1)

            close(s->fd);

    }

    qemu_free(s);



    return ret;

}

