    sub->rects[0]  = av_mallocz(sizeof(*sub->rects[0]));

    sub->num_rects = 1;



    sub->rects[0]->x    = ctx->presentation.x;

    sub->rects[0]->y    = ctx->presentation.y;

    sub->rects[0]->w    = ctx->picture.w;

    sub->rects[0]->h    = ctx->picture.h;

    sub->rects[0]->type = SUBTITLE_BITMAP;



