timer_write(void *opaque, target_phys_addr_t addr,

            uint64_t val64, unsigned int size)

{

    struct etrax_timer *t = opaque;

    uint32_t value = val64;



    switch (addr)

    {

        case RW_TMR0_DIV:

            t->rw_tmr0_div = value;

            break;

        case RW_TMR0_CTRL:

